    SET @fecha_ejecucion = CAST(@clean AS datetime2);
  ELSE
    SET @fecha_ejecucion = NULL;
END;

/* Insert del registro en el historial */
INSERT INTO OpsObservability.dbo.monitoring_job_errors_history(
  ts_utc,
  instance_name,
  job_name,
  step_name,
  mensaje,
  fecha_ejecucion,
  estado
)
VALUES(
  SYSUTCDATETIME(),
  @instance_name,
  @job_name,
  @step_name,
  @mensaje,
