  "- Los pasos afectados no finalizaron correctamente y pueden impactar procesos de negocio (backups, ETL, integraciones, etc.)."
].join("\n");

const sugg = [
  "- Revisar el historial del job en SQL Server Agent y validar el detalle del error.",
  "- Confirmar conectividad a orígenes/destinos (bases, archivos, redes) usados por el job.",
  "- Verificar permisos de las cuentas de servicio y rutas de archivos involucradas.",
  "- Ajustar programación o dividir pasos pesados si el error está asociado a tiempos de ejecución largos."
].join("\n");

const title = `${P.title_prefix || "ALERTA – Errores en Jobs SQL"} • ${inst}`;

return {
  json: {
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: "C0392B",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text: `🔴 **ALERTA – Errores detectados en Jobs de SQL Server**\n\nInstancia: **${inst}**\nJobs en alerta en esta ejecución: **${alerts.length}**\nHora local: ${toLocal(nowIso)}`
      },
      {
        markdown: true,
        text: `📄 **Detalle de jobs con error**\n\n${lines.join("\n")}`
      },
      {
        markdown: true,
        text: `📌 **Diagnóstico posible**\n${diag}`
      },
      {
        markdown: true,
        text: `✅ **Sugerencias**\n${sugg}`
      }
    ]
  }
};

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (RECOVERY) — Errores en Jobs ===
const j = $json;

const recovered   = j.recovered_items || [];
const stillAlerts = j.alerts || [];

let title = "";
const lines = [];

// Global vs parcial
if (j.send_recovery_global) {
  title = "RECOVERY – Errores en Jobs (todos OK)";
  lines.push(
    "Todos los jobs monitoreados por el SP `usp_DetectarErroresJobs` están ahora en estado **OK** (sin errores activos)."
  );
} else {
  title = "RECOVERY parcial – Errores en Jobs";
  lines.push(
    "Algunos jobs se han recuperado, pero aún quedan jobs en **ALERTA** por errores recientes."
  );
}

// Registros recuperados
if (recovered.length) {
  lines.push("");
  lines.push(`**Jobs recuperados (${recovered.length}):**`);
  lines.push("");

  recovered.forEach(r => {
    const jobName   = r.NombreJob  || r.job_name  || "N/D";
    const stepName  = r.NombreStep || r.step_name || "N/D";
    const estado    = r.Estado     || r.estado    || "OK";
    const fecha     = r.FechaEjecucion || r.fecha_ejecucion || r.ts_sp || r.Fecha || r.fecha || "N/D";

    lines.push(`- **Job:** ${jobName}  •  **Step:** ${stepName}  •  Último estado registrado: ${estado}  •  Último evento en alerta: ${fecha}`);
  });
}

// Registros que siguen en alerta
if (stillAlerts.length) {
  lines.push("");
  lines.push(`**Jobs que siguen en alerta (${stillAlerts.length}):**`);
  lines.push("");

  stillAlerts.forEach(r => {
    const jobName   = r.NombreJob  || r.job_name  || "N/D";
    const stepName  = r.NombreStep || r.step_name || "N/D";
    const estado    = r.Estado     || r.estado    || "Alerta";

    lines.push(`- **Job:** ${jobName}  •  **Step:** ${stepName}  •  Estado actual: ${estado}`);
  });
}

const text = `### ${title}\n\n` + lines.join("\n");

return [
  {
    json: {
      body: toAdaptiveCardBody(text),
    },
  },
];
